I have worked around the issue by creating the following class.
{code:java}
class MockFixedKeyProcessorContext[KForward, VForward]
    extends MockProcessorContext[KForward, VForward]
    with FixedKeyProcessorContext[KForward, VForward] {

  override def forward[K <: KForward, V <: VForward](record: FixedKeyRecord[K, V]): Unit =
    super.forward(new Record(record.key(), record.value(), record.timestamp(), record.headers()))

  override def forward[K <: KForward, V <: VForward](record: FixedKeyRecord[K, V], childName: String): Unit =
    super.forward(new Record(record.key(), record.value(), record.timestamp(), record.headers()), childName)
} {code}

